        let normalized = if index < glob_match_count {
            let expanded_dots = nu_path::dots::expand_dots(Path::new(&path_string));
            let normalized = expanded_dots.to_string_lossy().into_owned();
            if normalized.is_empty() {
                path_string
            } else {
                normalized
            }
        } else {
            path_string
        };

